-- How many qualifying entries have no matching lap_times?
SELECT COUNT(*) FROM qualifying q 
WHERE NOT EXISTS (SELECT 1 FROM lap_times lt WHERE lt.rc_index = q.qualkey);

-- Let's parse a time string to seconds
SELECT '1:12.812'::text as timestr,
       EXTRACT(EPOCH FROM ('00:' || '1:12.812')::interval) as seconds;

-- Check if avg_deficit should be numeric vs real, and verify column names
-- Let me also check if maybe driver_identity jsonb has a name field we need to use
SELECT * FROM drivers LIMIT 3;

-- Count distinct drivers in qualifying that also exist in drivers table
SELECT COUNT(DISTINCT q.pilotrec) FROM qualifying q 
JOIN drivers d ON q.pilotrec = d.drv_main;

-- Test LEAST behavior with NULLs
SELECT LEAST(NULL, 10, 20) as test1, 
       COALESCE(10, 20, 30) as test2;
